begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('16000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','delivery-mm@example.test','internal-otp-hash',now(),'{}','{}',now(),now()),
('16000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','delivery-employee@example.test','internal-otp-hash',now(),'{}','{"passwordSetupRequired":false}',now(),now());
insert into public.workspaces(id,name,owner_id) values('26000000-0000-4000-8000-000000000001','Delivery fixture','16000000-0000-4000-8000-000000000001');
insert into public.workspace_members(workspace_id,user_id,role) values('26000000-0000-4000-8000-000000000001','16000000-0000-4000-8000-000000000001','admin');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"16000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.membership_onboarding_state()->>'passwordSetupRequired','true','internal OTP hash is not a user-set password');
select throws_ok($$select * from membership_private.password_setup$$,'42501',null,'client cannot read private password state');
select throws_ok($$update membership_private.password_setup set completed=true$$,'42501',null,'client cannot complete password step');
select throws_ok($$select public.membership_company_directory('',null,0)$$,'P0001','VALIDATION_ERROR','null pagination cannot bypass directory limit');
reset role;
update auth.users set encrypted_password='user-changed-password' where id='16000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(public.membership_onboarding_state()->>'passwordSetupRequired','false','subsequent Auth password change completes setup');
select set_config('request.jwt.claims','{"sub":"16000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.membership_invite('26000000-0000-4000-8000-000000000001','delivery-employee@example.test','member',null)$$,'create delivery invitation');
select lives_ok($$select public.membership_invite('26000000-0000-4000-8000-000000000001','delivery-employee@example.test','member',null)$$,'duplicate invitation idempotent');
select is((select count(*)::int from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001'),1,'only one invitation');
select lives_ok($$select public.membership_claim_delivery('26000000-0000-4000-8000-000000000001',(select id from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' limit 1))$$,'claim delivery lease');
select throws_ok($$select public.membership_claim_delivery('26000000-0000-4000-8000-000000000001',(select id from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' limit 1))$$,'P0001','RATE_LIMITED','duplicate delivery blocked by lease/cooldown');
reset role;
set local role service_role;
select throws_ok($$select public.membership_record_delivery((select id from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' limit 1),gen_random_uuid(),true)$$,'P0001','REQUEST_CLOSED','stale delivery cannot overwrite current attempt');
select lives_ok($$select public.membership_record_delivery((select id from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' limit 1),(select delivery_attempt_id from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' limit 1),false)$$,'provider failure recorded');
select is((select delivery_status from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' limit 1),'failed','failure never becomes sent');
reset role;
update public.workspace_invitations set expires_at=now()-interval '1 second' where workspace_id='26000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"16000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.membership_accept_invitation((select id from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' limit 1))$$,'P0001','INVITATION_EXPIRED','expired invitation grants nothing');
select is((select count(*)::int from public.workspace_members where user_id=auth.uid()),0,'still no membership');
select set_config('request.jwt.claims','{"sub":"16000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.membership_invite('26000000-0000-4000-8000-000000000001','delivery-employee@example.test','member',null)$$,'new invitation replaces expired pending');
select lives_ok($$select public.membership_revoke_invitation('26000000-0000-4000-8000-000000000001',(select id from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' and status='pending'))$$,'manager revokes pending invitation');
select set_config('request.jwt.claims','{"sub":"16000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.membership_accept_invitation((select id from public.workspace_invitations where workspace_id='26000000-0000-4000-8000-000000000001' order by created_at desc,id desc limit 1))$$,'P0001','INVITATION_REVOKED','revoked invitation grants nothing');
select is((public.membership_list_notifications(false,20,0)->>'unreadCount')::int,2,'recipient sees only own invitation notifications');
select throws_ok($$select public.membership_read_notification(gen_random_uuid())$$,'P0001','PERMISSION_DENIED','unknown recipient resource cannot be marked read');
select * from finish();
rollback;
